R.check("L0-SRC-pr-pin", "L0", "source", "catalogue entry at PR head 1f4e993: sha/version", "sha 9a712f9..., version 1.0.1, matching plugin.yaml at that commit", "sha: 9a712f9714ff5687425f0ffc9ac7eb6f9eb441cb, version 1.0.1; plugin.yaml version 1.0.1", "version: 1.0.1" in (W / "plugin.yaml").read_text(), mode="git")
