    R.check(f"L0-VALIDATE-{rev}", "L0", "baseline", f"hermes plugins validate . --install-deps at rev {rev}", "Validation passed", "15 checks pass; security scan safe; Validation passed", "Validation passed." in part and "security scan — safe" in part, rev=rev, mode="hermes-cli")
