R.check("L1-DOCTOR-verbatim", "L1", "install", "`hermes plugins doctor crash-lab --ci`", "exit 0, 4 tools", "registrations: 4 tool(s), 0 hook(s)", inst.count("registrations: 4 tool(s)") == 1, mode="hermes-cli")
