R.check("REL-EVID-revision", "REL", "evidence", "bundled traces, oracle sweep and review were produced by the code they sit beside (1.0.1)", "evidence generated at 9a712f9 (retry_count field and 1.0.1 scope string present)", f"`git diff --stat 44c8071 9a712f9` touches no file under evidence/; traces contain 'retry_count' {txt.count('retry_count')} times; scope string is the 1.0.0 wording in all 5 traces and all 9 oracle-sweep entries", "retry_count" in txt, defect="CRASH-AUD-018")
