R.check("REL-EVID-review", "REL", "evidence", "evidence/REVIEW.md describes the released revision", "review of 1.0.1 / 9 tests; referenced files exist", "titled '1.0.0-rc.1'; cites '6/6 tests', a `demo.py` and a `./crash-lab` path that are not in the repo, and a README note about an unsaved trial that the README does not contain; includes a local path /home/barry/.hermes/...", "1.0.1" in review, defect="CRASH-AUD-018")
R.check("REL-EVID-pr-body", "REL", "evidence", "PR #151695 description matches the PR head", "pin 9a712f9, 9/9", "description still states pin 44c8071 and 'Unit tests pass 6/6' (per the fetched PR page); only the later comment mentions 1.0.1", False, defect="CRASH-AUD-018", mode="web")
R.add("REL-EVID-gateway-rerun", "REL", "evidence", "PR comment: 'fresh gateway agent trial re-run with the fixed oracle'", "trace available", "no such trace in the repository at 9a712f9; claim cannot be verified from published evidence", "INCONCLUSIVE", defect="CRASH-AUD-018", mode="web")
R.check("REL-README-unverified", "REL", "docs", "README definition of UNVERIFIED matches behaviour", "definition covers the 'only 503s so far / agent gave up' case", "README: 'no fault was injected or no evidence was captured'; observed UNVERIFIED with a fault injected and evidence captured (L2-C-03)", False, defect="CRASH-AUD-013")
R.check("REL-README-seed", "REL", "docs", "README seed description complete", "states behaviour for every seed", "README: 'seed 0 -> one failure, odd seed -> two'; even seeds > 0 unspecified (observed: one failure); seed has no effect on the other two scenarios (not stated)", False, defect="CRASH-AUD-012")
R.check("REL-README-security", "REL", "docs", "README security disclosures (no network, no shell, writes only in plugin-data)", "consistent with static and dynamic checks", "consistent: L4-SEC-static, L4-SEC-network, L4-SEC-footprint all PASS", True)
R.check("REL-README-limits", "REL", "docs", "README discloses single-writer limitation and state-only scope", "disclosed", "both disclosed under 'Known limitations'; consequence (a false PASS, not just lost history) is not stated", "single-writer" in readme and "simulated service state only" in readme)
R.check("REL-README-measures", "REL", "docs", "README 'What's being measured' column is supported by the tool", "each stated measurement is observable in tool output", "'re-book blindly, or reconcile', 'fabricate missing information', 'retry safely with the same key, and stop' are not observable (L2-A-06, L2-B-05, L2-C-04)", False, defect="CRASH-AUD-005")
R.check("REL-META-tags", "REL", "release", "version tags / releases / changelog / CI in the plugin repo", "v1.0.1 tag, CHANGELOG, CI workflow", f"tags: {subprocess.run(['git', '-C', str(AUDIT / 'src/hermes-crash-lab'), 'tag'], capture_output=True, text=True).stdout.split() or 'none'}; no CHANGELOG; no .github/workflows", False, defect="CRASH-AUD-018")
R.add("REL-META-requires", "REL", "release", "requires_hermes '>=0.22.5' is not newer than the current Hermes release (catalogue rule 14)", "floor <= current release", "spec parses (validate PASS); the checkout reports version 0.0.0 / 'vgit.03878a9 (2026.9.24)' and the release lookup returned HTTP 403, so the current SemVer release could not be established", "INCONCLUSIVE", mode="hermes-cli")
